async function refreshAuth(){if(!auth||!auth.refresh_token||!auth.expires_at||auth.expires_at*1000>Date.now()+60000)return;try{const r=await fetch(URL+"/auth/v1/token?grant_type=refresh_token",{method:"POST",headers:{apikey:KEY,"Content-Type":"application/json"},body:JSON.stringify({refresh_token:auth.refresh_token})});const d=await r.json();if(!r.ok||!d.access_token){saveAuth(null);return;}saveAuth({...d,expires_at:Math.floor(Date.now()/1000)+Number(d.expires_in||3600)});}catch(_){}}
