async function authCall(path,body){const r=await fetch(URL+path,{method:"POST",headers:{apikey:KEY,"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify(body)});let d={};try{d=await r.json();}catch(_){}if(!r.ok)throw new Error(d.msg||d.message||d.error_description||"Authentication failed.");return d;}
