 const cf=$("#checkout-form");if(cf){const calc=()=>{const a=$("#checkout-in").value,b=$("#checkout-out").value,n=validDates(a,b)?nights(a,b):0,rr=(catalog||[]).flatMap(p=>p.rooms||[]).find(x=>x.id===cf.dataset.room);$("#checkout-nights").textContent=n?n+" night(s)":"—";$("#checkout-total").textContent=n&&rr?money(Number(rr.base_price)*n):"—";};["checkout-in","checkout-out"].forEach(id=>$("#"+id).addEventListener("change",calc));calc();cf.addEventListener("submit",async e=>{e.preventDefault();const f=new FormData(cf),a=String(f.get("check_in")||""),b=String(f.get("check_out")||""),adults=Number(f.get("adults")),children=Number(f.get("children")),box=$("#checkout-message"),btn=$("#checkout-submit");box.innerHTML="";if(!validDates(a,b)||nights(a,b)>60){box.innerHTML=note("Choose valid dates for 1–60 nights.","error");return;}btn.disabled=true;btn.textContent="Checking availability…";try{const av=await callEdge("stays-bookings","POST",{action:"availability",room_unit_id:cf.dataset.room,check_in:a,check_out:b,adults,children});if(!av.available){box.innerHTML=note("Those dates are not available. Choose other dates and try again.","error");return;}btn.textContent="Saving request…";const d=await callEdge("stays-bookings","POST",{action:"create",room_unit_id:cf.dataset.room,guest_name:f.get("guest_name"),guest_email:f.get("guest_email"),guest_phone:f.get("guest_phone"),check_in:a,check_out:b,adults,children,special_requests:f.get("special_requests")});const p=(catalog||[]).find(x=>x.id===cf.dataset.property),save={reference:d.booking_reference,token:d.access_token,propertyName:p?p.name:"Uttarkunth stay",savedAt:new Date().toISOString()};saveBooking(save);noticeNext="Booking request saved. It is still pending host confirmation.";go("/stays/booking?ref="+encodeURIComponent(save.reference));}catch(err){box.innerHTML=note(err.message,"error");}finally{btn.disabled=false;btn.textContent="Check availability & send request ↗";}});}
 const af=$("#auth-form");if(af)af.addEventListener("submit",async e=>{e.preventDefault();const f=new FormData(af),mode=af.dataset.mode,target=af.dataset.target,box=$("#auth-result"),btn=$("button[type=submit],button:not([type])",af);btn.disabled=true;box.innerHTML=spinner(mode==="signup"?"Creating account…":"Signing in…");try{if(mode==="signup"){const d=await signUp(String(f.get("full_name")||""),String(f.get("email")||"").trim().toLowerCase(),String(f.get("password")||""));if(d.access_token){go(target==="host"?"/stays/host":target==="admin"?"/stays/admin":"/stays/account");}else box.innerHTML=note("Account created. Check your email to confirm your address, then return here to sign in. Host tools require verified email.","");}else{await signIn(String(f.get("email")||"").trim().toLowerCase(),String(f.get("password")||""));go(target==="host"?"/stays/host":target==="admin"?"/stays/admin":"/stays/account");}}catch(err){box.innerHTML=note(err.message,"error");}finally{btn.disabled=false;}});
