 const hp=$("#host-property-form");if(hp)hp.addEventListener("submit",async e=>{e.preventDefault();const f=new FormData(hp),box=$("#host-property-result"),btn=$("button[type=submit],button:not([type])",hp);const body={action:"property.create",name:f.get("name"),property_type:f.get("property_type"),village:f.get("village"),district:f.get("district"),state:f.get("state"),address:f.get("address"),description:f.get("description"),amenities:String(f.get("amenities")||"").split(",").map(x=>x.trim()).filter(Boolean),room_name:f.get("room_name"),base_price:f.get("base_price"),max_guests:f.get("max_guests"),room_description:f.get("room_description")};btn.disabled=true;box.innerHTML=spinner("Saving listing…");try{const d=await callEdge("stays-host","POST",body);catalog=null;box.innerHTML=note(d.message||"Listing submitted for review.");setTimeout(()=>go("/stays/host?tab=listings"),700);}catch(err){box.innerHTML=note(err.message,"error");}finally{btn.disabled=false;}});
