function modal(title,body){const root=$("#modal-root");root.innerHTML='<div class="modal-backdrop" id="modal-backdrop"><div class="modal"><div class="modal-head"><h2>'+esc(title)+'</h2><button type="button" id="modal-close" class="modal-close">×</button></div><div class="modal-content">'+body+'</div></div></div>';$("#modal-close").addEventListener("click",()=>root.innerHTML="");$("#modal-backdrop").addEventListener("click",e=>{if(e.target.id==="modal-backdrop")root.innerHTML="";});}
document.addEventListener("click",async e=>{const a=e.target.closest("a");if(a&&a.origin===location.origin&&a.pathname.startsWith("/stays")&&!a.target&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&a.getAttribute("href")!=="#"){e.preventDefault();go(a.pathname+a.search+a.hash);return;}const b=e.target.closest("button");if(!b)return;if(b.id==="mobile-menu"){modal("Explore Uttarkunth Stays",'<div class="list-rows"><a class="btn btn-green" href="/stays/">Explore</a><a class="btn btn-ghost" href="/stays/search">Search stays</a><a class="btn btn-ghost" href="/stays/trips">Your trips</a><a class="btn btn-ghost" href="/stays/account">Account</a><a class="btn btn-ghost" href="/stays/host">Host workspace</a><a class="btn btn-ghost" href="/stays/admin">Platform desk</a></div>');return;}if(b.dataset.nav){go(b.dataset.nav);return;}if(b.dataset.authMode){const r=route(),base=r.name==="host"?"/stays/host?mode=":r.name==="admin"?"/stays/admin?mode=":"/stays/account?mode=";go(base+b.dataset.authMode);return;}const action=b.dataset.action;if(action==="refresh"){catalog=null;catalogTime=0;go(location.pathname+location.search);return;}if(action==="logout"){await signOut();return;}if(action==="fav"){const list=savedFavs(),i=list.indexOf(b.dataset.id);if(i>=0)list.splice(i,1);else list.push(b.dataset.id);localStorage.setItem(FAV,JSON.stringify(list));catalog=null;go(location.pathname+location.search);return;}if(action==="host-decision"){if(!confirm((b.dataset.decision==="confirm"?"Accept":"Decline")+" this booking request? Confirming reserves the room dates."))return;const notes=prompt("Optional host note:","")||"";b.disabled=true;try{await callEdge("stays-host","POST",{action:"booking.decision",booking_id:b.dataset.id,decision:b.dataset.decision,host_notes:notes});noticeNext="Booking request updated.";go("/stays/host?tab=bookings");}catch(err){alert(err.message);b.disabled=false;}return;}if(action==="moderate"){const status=b.dataset.status,noteText=["rejected","changes_requested"].includes(status)?prompt("Add a brief review note for the host:","")||"":"";if(status==="approved"&&!confirm("Approve and publish this listing? Check ownership and content first."))return;if(["rejected","suspended"].includes(status)&&!confirm("Set listing status to "+status+"?"))return;b.disabled=true;try{await callEdge("stays-admin","POST",{action:"property.moderate",property_id:b.dataset.id,status,note:noteText});noticeNext="Property moderation saved.";go("/stays/admin?tab=properties");}catch(err){alert(err.message);b.disabled=false;}return;}if(action==="admin-booking"){if(!confirm("Apply booking decision "+b.dataset.decision+"?"))return;b.disabled=true;try{await callEdge("stays-admin","POST",{action:"booking.decision",booking_id:b.dataset.id,decision:b.dataset.decision,note:""});noticeNext="Booking decision saved.";go("/stays/admin?tab=bookings");}catch(err){alert(err.message);b.disabled=false;}return;}if(action==="submit-property"){try{const d=await callEdge("stays-host","POST",{action:"property.submit",property_id:b.dataset.id});noticeNext=d.message||"Submitted for review.";go("/stays/host?tab=listings");}catch(err){alert(err.message);}return;}if(action==="edit-property"){const ps=await callEdge("stays-host","GET"),p=(ps.properties||[]).find(x=>x.id===b.dataset.id);if(!p)return;const name=prompt("Property name:",p.name);if(name===null)return;const village=prompt("Village / town:",p.village||"");if(village===null)return;const district=prompt("District:",p.district||"");if(district===null)return;const desc=prompt("Description:",p.description||"");if(desc===null)return;try{await callEdge("stays-host","POST",{action:"property.update",property_id:p.id,name,village,district,description:desc});noticeNext="Property changes saved and sent for review.";go("/stays/host?tab=listings");}catch(err){alert(err.message);}return;}if(action==="upload-property"){const pId=b.dataset.id;modal("Upload property photo",'<p class="muted" style="font-size:11px">Use JPG, PNG, WebP or AVIF, up to 8 MB. Uploading triggers a new review.</p><form id="quick-upload" data-id="'+esc(pId)+'"><div class="form-field"><label>Photo</label><input type="file" name="file" required accept="image/jpeg,image/png,image/webp,image/avif"></div><div id="quick-upload-result"></div><button class="btn btn-green" style="margin-top:14px">Upload image</button></form>');$("#quick-upload").addEventListener("submit",async ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget),box=$("#quick-upload-result");f.append("action","upload-photo");f.append("property_id",pId);box.innerHTML=spinner("Uploading…");try{const d=await callEdge("stays-host","POST",f);box.innerHTML=note(d.message||"Uploaded.");setTimeout(()=>go("/stays/host?tab=listings"),700);}catch(err){box.innerHTML=note(err.message,"error");}});return;}if(action==="edit-room"){const res=await callEdge("stays-host","GET"),room=(res.rooms||[]).find(x=>x.id===b.dataset.id);if(!room)return;const name=prompt("Room type name:",room.room_name);if(name===null)return;const rate=prompt("Nightly rate (INR):",room.base_price);if(rate===null)return;const cap=prompt("Maximum guests:",room.max_guests);if(cap===null)return;const desc=prompt("Room description:",room.description||"");if(desc===null)return;try{await callEdge("stays-host","POST",{action:"room.update",room_id:room.id,property_id:room.property_id,room_name:name,base_price:rate,max_guests:cap,description:desc});noticeNext="Room changes saved; listing requires review.";go("/stays/host?tab=rooms");}catch(err){alert(err.message);}return;}if(action==="unblock"){if(!confirm("Remove this availability block?"))return;try{await callEdge("stays-host","POST",{action:"availability.unblock",block_id:b.dataset.id});noticeNext="Availability block removed.";go("/stays/host?tab=calendar");}catch(err){alert(err.message);}return;}if(action==="track-saved"){const item=savedBookings().find(x=>x.reference===b.dataset.ref),box=$("#trip-status");if(!item||!box)return;box.innerHTML=spinner("Looking up booking…");try{const d=await callEdge("stays-bookings","POST",{action:"track",booking_reference:item.reference,access_token:item.token}),bk=d.booking;box.innerHTML='<div class="panel"><div class="panel-head"><div><h2>'+esc((bk.property||{}).name||item.propertyName||"Stay request")+'</h2><p>'+esc(bk.booking_reference)+'</p></div>'+pill(bk.status)+'</div><div class="panel-body"><p>'+esc(dateFmt(bk.check_in))+' → '+esc(dateFmt(bk.check_out))+' · '+money(bk.total_estimate)+'</p>'+(bk.status==="pending"?'<button class="btn btn-danger" data-action="cancel-saved" data-ref="'+esc(item.reference)+'">Cancel pending request</button>':"")+'</div></div>';}catch(err){box.innerHTML=note(err.message,"error");}return;}if(action==="cancel-saved"){const item=savedBookings().find(x=>x.reference===b.dataset.ref);if(!item||!confirm("Cancel this pending request?"))return;try{await callEdge("stays-bookings","POST",{action:"cancel",booking_reference:item.reference,access_token:item.token});$("#trip-status").innerHTML=note("Booking request cancelled.");}catch(err){$("#trip-status").innerHTML=note(err.message,"error");}return;}if(action==="show-token"){const item=savedBookings().find(x=>x.reference===b.dataset.ref);if(!item)return;modal("Private booking credentials",'<p class="muted" style="font-size:11px">Keep this token private.</p><div class="label">Reference</div><div class="copy-token">'+esc(item.reference)+'</div><div class="label" style="margin-top:12px">Access token</div><div class="copy-token">'+esc(item.token)+'</div><button class="btn btn-green" id="copy-modal-token" style="margin-top:14px">Copy details</button>');$("#copy-modal-token").addEventListener("click",async()=>{try{await navigator.clipboard.writeText("Reference: "+item.reference+"\nAccess token: "+item.token);$("#copy-modal-token").textContent="Copied";}catch(_){}});return;}if(action==="cancel-current"){if(!confirm("Cancel this pending request?"))return;try{await callEdge("stays-bookings","POST",{action:"cancel",booking_reference:b.dataset.ref,access_token:b.dataset.token});$("#track-result").innerHTML=note("Booking request cancelled.");}catch(err){$("#track-result").innerHTML=note(err.message,"error");}return;}});
